	@Test
	void foregroundExactSupportUsesTheExecutingQueryPair(@TempDir File directory) {
		ProbeStore store = new ProbeStore(directory);
		SailRepository repository = new SailRepository(store);
		repository.init();
		try (RepositoryConnection reader = repository.getConnection();
				RepositoryConnection writer = repository.getConnection()) {
			writer.add(A, P, VF.createLiteral("5", XSD.INTEGER));
			writer.add(C, P, VF.createLiteral("5", XSD.INT));
			reader.begin(IsolationLevels.SNAPSHOT);
			assertEquals(Set.of(A.stringValue(), C.stringValue()), rows(reader, false));
			writer.remove(C, P, VF.createLiteral("5", XSD.INT));
			assertEquals(Set.of(A.stringValue(), C.stringValue()), rows(reader, false));
			Set<String> filtered = rows(reader, true);
			System.err.println("Foreground exact support observations: " + store.observations);
			assertAll(
					() -> assertEquals(Set.of(A.stringValue(), C.stringValue()), filtered,
							"a current probe must not remove a term visible in the pinned query"),
					() -> assertFalse(store.observations.isEmpty(), "the query must exercise exact support"),
					() -> assertEquals(true, store.observations.stream().allMatch(ProbeObservation::samePair),
							"foreground support must use the actual query transaction and dictionary: "
									+ store.observations));
			reader.commit();
		} finally {
			repository.shutDown();
		}
	}

