	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void liveUnprovedInnerCompositionExecutesAndRestoresOuter(boolean failCallback, @TempDir File directory) {
		ProbeStore store = new ProbeStore(directory);
		SailRepository repository = new SailRepository(store);
		repository.init();
		try (RepositoryConnection writer = repository.getConnection()) {
			writer.add(A, P, VF.createLiteral("5", XSD.INTEGER));
			try (PlanningInvocation outer = new PlanningInvocation(store)) {
				writer.add(C, P, VF.createLiteral("5", XSD.INT));
				try (PlanningInvocation second = new PlanningInvocation(store);
						PlanningInvocation inner = new PlanningInvocation(store,
								opaque(union(outer.dataset, second.dataset)))) {
					List<String> expected = List.of(A.stringValue(), A.stringValue(), C.stringValue());
					assertEquals(expected, subjects(inner, filteredInput()),
							"the original composed source must execute");
					RuntimeException failure = new IllegalStateException("unproved inner callback failed");
					outer.pipeline.withPreparedQueryEntry(new QueryRoot(new SingletonSet()), null,
							EmptyBindingSet.getInstance(), (prepared, cascades) -> {
								int probes = store.probeAdmissions.get();
								Supplier<TupleExpr> planInner = () -> inner.pipeline.withPreparedQueryEntry(
										filteredInput(), null, EmptyBindingSet.getInstance(),
										(unproved, innerCascades) -> {
											assertFalse(store.triples.planningReadsPinned(),
													"NONE must mask the outer triple authority");
											assertNull(store.values.borrowedPlanningSnapshot(),
													"NONE must mask the outer dictionary authority");
											assertTrue(store.getBackingStore().currentReadResourceViews().isEmpty(),
													"NONE must hide captured outer resource candidates");
											assertThrows(CascadesPlanningException.class,
													() -> innerCascades.auditPreparedInput(unproved, null, 1,
															1_000_000));
											if (failCallback) {
												throw failure;
											}
											TupleExpr plan = innerCascades.optimizeWithResult(unproved, null,
													EmptyBindingSet.getInstance()).installedPlan();
											assertNotEquals("true",
													plan.getStringMetricPlanned("optimizer.pipelinePlanCacheHit"));
											assertNotEquals("true",
													plan.getStringMetricPlanned("optimizer.cascadesPlanCacheHit"));
											assertEquals(
													LmdbCascadesOptimizer.FEEDBACK_PUBLICATION_SUPPRESSED_UNCOMMITTED,
													plan.getStringMetricPlanned(
															LmdbCascadesOptimizer.PLANNED_FEEDBACK_PUBLICATION_METRIC));
											return plan;
										});
								if (failCallback) {
									assertSame(failure, assertThrows(RuntimeException.class, planInner::get));
								} else {
									var planned = planInner.get();
									assertActivePair(store, outer);
									assertEquals(expected, subjects(inner, planned));
								}
								assertEquals(probes, store.probeAdmissions.get(),
										"NONE must decline native proof probes");
								assertActivePair(store, outer);
								return null;
							});
					assertFalse(store.triples.planningReadsPinned());
					assertNull(store.values.borrowedPlanningSnapshot());
				}
			}
		} finally {
			repository.shutDown();
		}
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void unprovedScopeRestoresAcrossAQualifiedNestedQuery(boolean failQualifiedCallback, @TempDir File directory) {
		ProbeStore store = new ProbeStore(directory);
		SailRepository repository = new SailRepository(store);
		repository.init();
		try (RepositoryConnection writer = repository.getConnection()) {
			writer.add(A, P, VF.createLiteral("5", XSD.INTEGER));
			try (PlanningInvocation outer = new PlanningInvocation(store)) {
				writer.add(C, P, VF.createLiteral("5", XSD.INT));
				try (PlanningInvocation qualified = new PlanningInvocation(store);
						PlanningInvocation unproved = new PlanningInvocation(store,
								opaque(union(outer.dataset, qualified.dataset)))) {
					RuntimeException failure = new IllegalStateException("qualified inner callback failed");
					outer.pipeline.withPreparedQueryEntry(new QueryRoot(new SingletonSet()), null,
							EmptyBindingSet.getInstance(), (outerInput, outerCascades) -> {
								TupleExpr plan = unproved.pipeline.withPreparedQueryEntry(filteredInput(), null,
										EmptyBindingSet.getInstance(), (noneInput, noneCascades) -> {
											assertFalse(store.triples.planningReadsPinned());
											assertNull(store.values.borrowedPlanningSnapshot());
											assertTrue(store.getBackingStore().currentReadResourceViews().isEmpty());
											int probes = store.probeAdmissions.get();
											Supplier<TupleExpr> inner = () -> qualified.pipeline.withPreparedQueryEntry(
													filteredInput(), null, EmptyBindingSet.getInstance(),
													(input, cascades) -> {
														assertActivePair(store, qualified);
														assertTrue(store.probeAdmissions.get() > probes);
														assertTrue(store.observations.stream()
																.allMatch(observation -> observation.samePair()
																		&& observation.queryTxn() == qualified.pinned
																				.pinnedReadTxn()
																				.orElseThrow()
																				.nativeTransactionId()));
														if (failQualifiedCallback) {
															throw failure;
														}
														return input;
													});
											if (failQualifiedCallback) {
												assertSame(failure, assertThrows(RuntimeException.class, inner::get));
											} else {
												inner.get();
											}
											assertFalse(store.triples.planningReadsPinned());
											assertNull(store.values.borrowedPlanningSnapshot());
											assertTrue(store.getBackingStore().currentReadResourceViews().isEmpty());
											int restoredProbes = store.probeAdmissions.get();
											TupleExpr result = noneCascades.optimizeWithResult(noneInput, null,
													EmptyBindingSet.getInstance()).installedPlan();
											assertEquals(restoredProbes, store.probeAdmissions.get());
											return result;
										});
								assertActivePair(store, outer);
								assertEquals(List.of(A.stringValue(), A.stringValue(), C.stringValue()),
										subjects(unproved, plan));
								return null;
							});
					assertFalse(store.triples.planningReadsPinned());
					assertNull(store.values.borrowedPlanningSnapshot());
				}
			}
		} finally {
			repository.shutDown();
		}
	}

	private static QueryRoot filteredInput() {
		return new QueryRoot(new Filter(new StatementPattern(new Var("s"), new Var("p", P), new Var("o")),
				new Compare(new Var("o"), new ValueConstant(VF.createLiteral(5)), Compare.CompareOp.EQ)));
	}

	private static List<String> subjects(PlanningInvocation invocation, TupleExpr expression) {
		List<String> result = new ArrayList<>();
		try (var rows = invocation.strategy.precompile(expression).evaluate(EmptyBindingSet.getInstance())) {
			while (rows.hasNext()) {
				result.add(rows.next().getValue("s").stringValue());
			}
		}
		Collections.sort(result);
		return result;
	}

