	@Test
	void pendingOverlayRowsDoNotUseCommittedExactSupport(@TempDir File directory) {
		ProbeStore store = new ProbeStore(directory);
		SailRepository repository = new SailRepository(store);
		repository.init();
		try (RepositoryConnection connection = repository.getConnection()) {
			connection.add(A, P, VF.createLiteral("5", XSD.INTEGER));
			connection.begin(IsolationLevels.SNAPSHOT);
			connection.add(C, P, VF.createLiteral("5", XSD.INT));
			assertEquals(Set.of(A.stringValue(), C.stringValue()), rows(connection, false));
			store.observations.clear();
			assertEquals(Set.of(A.stringValue(), C.stringValue()), rows(connection, true),
					"a committed base support cannot remove an uncommitted value-equal term");
			assertTrue(store.observations.isEmpty(),
					"an overlay without a published snapshot cannot use exact support");
			connection.rollback();
		} finally {
			repository.shutDown();
		}
	}

